WITH base AS (SELECT * FROM suppliers WHERE supplier_name LIKE 'G%' AND country IN ('DE', 'US') AND country NOT IN ('JP', 'DE', 'TH')), RatingBucketSummary AS (SELECT CASE WHEN rating >= 3.5 THEN 'high' WHEN rating >= 1.6 THEN 'mid' ELSE 'low' END AS rating_bucket, MAX(rating) - MIN(rating) AS rating_range, COUNT(CASE WHEN country = 'TH' THEN 1 END) AS th_count FROM base GROUP BY CASE WHEN rating >= 3.5 THEN 'high' WHEN rating >= 1.6 THEN 'mid' ELSE 'low' END) SELECT * FROM RatingBucketSummary WHERE th_count >= 9 ORDER BY rating_bucket DESC
